# Generate a fiscal year's twelve monthly periods, as the period generator does.
validate:
  class: net.officefloor.hq.app.period.ValidateGenerateFiscalYear
  next: generate
generate:
  class: net.officefloor.hq.app.period.GeneratePeriods
  govern: [ transaction ]
# The opening import box: lines of name,period,amount, each adding its amount to the person's opening
# for the period (part of their carried figure for it). Every line is checked before any is taken;
# one refused line takes none.
validate:
  class: net.officefloor.hq.app.opening.ValidateImportOpenings
  next: save
save:
  class: net.officefloor.hq.app.opening.SaveImportOpenings
  govern: [ transaction ]
package net.officefloor.hq.app.period;

import java.time.LocalDate;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.setting.ViewerRefusedException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

/** A fiscal year's months: from the first day of the sheet's fiscal start month in the year, for twelve months. */
public class ValidateGenerateFiscalYear {

    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody GenerateFiscalYearRequest request,
            Out<ValidGenerate> body, Settings settings)
            throws InvalidPeriodException, ViewerRefusedException {
        settings.refuseViewer(sheetId, request.user());
        String year = request.year() == null ? "" : request.year().trim();
        if (!year.matches("\\d{4}")) {
            throw new InvalidPeriodException("The fiscal year must be a year (YYYY)");
        }
        LocalDate from = LocalDate.of(Integer.parseInt(year), settings.fiscalStartMonth(sheetId), 1);
        body.set(new ValidGenerate(from, from.plusMonths(12).minusDays(1), request.user()));
    }
}
package net.officefloor.hq.app.period;

/** Body of POST /api/sheets/{sheetId}/periods/generate-fy: the fiscal year (yyyy, named FY<yyyy> by the calendar
 *  year its first day falls in) whose twelve months each become a period. */
public record GenerateFiscalYearRequest(String year, String user) {
}
package net.officefloor.hq.app.period;

import java.time.LocalDate;

/** A generate request that passed validation: a from-date on or before its to-date. */
public record ValidGenerate(LocalDate from, LocalDate to, String user) {
}
package net.officefloor.hq.app.period;

import java.time.YearMonth;
import net.officefloor.hq.app.Audit;
import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;

/** One period per calendar month from the from-date's month to the to-date's month, named yyyy-mm and
 *  running from its first to its last day; a month whose name is taken, or whose days overlap a period
 *  on the sheet, is left out. */
public class GeneratePeriods {
    public void generate(@PathVariable("sheetId") String sheetId, @Val ValidGenerate request, Periods periods,
            Audit audit, ObjectResponse<GenerateResponse> response) {
        int generated = 0;
        YearMonth last = YearMonth.from(request.to());
        for (YearMonth month = YearMonth.from(request.from()); !month.isAfter(last); month = month.plusMonths(1)) {
            ValidPeriod period = new ValidPeriod(month.toString(), month.atDay(1), month.atEndOfMonth(),
                    request.user());
            if (periods.addIfFree(sheetId, period)) {
                generated++;
                audit.recordOnCommit("PERIOD_ADDED sheet=" + sheetId + " by=" + period.user()
                        + " period=" + period.name() + " from=" + period.from() + " to=" + period.to());
            }
        }
        response.send(new GenerateResponse(generated, periods.list(sheetId)));
    }
}
package net.officefloor.hq.app.period;

import java.util.List;

/** How many monthly periods were made, and the sheet's periods after. */
public record GenerateResponse(int generated, List<PeriodResponse> periods) {
}
package net.officefloor.hq.app.period;

/** A period that cannot be added (no name, a name already on the sheet, a bad date, a from-date after
 *  its to-date, or dates overlapping another period); nothing is written. */
public class InvalidPeriodException extends Exception {
    public InvalidPeriodException(String message) {
        super(message);
    }
}
package net.officefloor.hq.app.period;

import net.officefloor.plugin.section.clazz.Parameter;
import net.officefloor.web.ObjectResponse;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;

public class HandleInvalidPeriod {
    public void handle(@Parameter InvalidPeriodException ex, ObjectResponse<ResponseEntity<String>> response) {
        response.send(new ResponseEntity<>(ex.getMessage(), HttpStatus.BAD_REQUEST));
    }
}

