            generate.reset();
          }}
        />{' '}
        <button type="submit" data-testid="period-generate">Generate monthly periods</button>
        {generated.isSuccess && (
          <>
            {' '}
            Made <span data-testid="period-generated">{generated.data.generated}</span>
          </>
        )}
        {generated.isError && (
          <span data-testid="period-generate-error" role="alert">
